int main(){mt19937 r(57);for(int t=0;t<200;t++){int n=1+r()%8;vector<vector<long long>> a(n,vector<long long>(n)),inv=a;vector<vector<long double>> x(n,vector<long double>(n)),y=x;for(int i=0;i<n;i++)for(int j=0;j<n;j++)x[i][j]=a[i][j]=i==j?100:int(r()%11)-5;for(int i=0;i<n;i++)inv[i][i]=y[i][i]=1;assert(solve_matrix_mod(a,inv,1000000007));assert(solve_matrix(x,y));for(int i=0;i<n;i++)for(int j=0;j<n;j++){long long z=0;long double v=0;for(int k=0;k<n;k++)z=((z+(__int128)a[i][k]*inv[k][j])%1000000007+1000000007)%1000000007,v+=x[i][k]*y[k][j];assert(z==(i==j)&&fabsl(v-(i==j))<1e-9);}}vector<vector<long long>> a={{0}},b={{1}};assert(!solve_matrix_mod(a,b,7));}
